insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0002-0000-4000-8000-00000000000c', 'en', null, 'IT Support Essentials', 'A hands-on foundation for the help desk: hardware, operating systems, a repeatable troubleshooting method, mobile devices and printers, security, and the people skills that close a ticket. Structure references the publicly published CompTIA A+ and Google IT Support objectives to target A+/IT-Support foundations; all prose is original.', null, 'work', 12, true, 'technology', '{bbbb0002-0000-4000-8000-000000000001}')
