insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0002-0000-4000-8000-00000000000c', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The main circuit board that everything else plugs into is the…","options":["power supply","motherboard","hard drive","GPU"],"answer":1,"explanation":"The motherboard connects CPU, RAM, storage, and expansion cards — covered in ''Hardware''."},{"prompt":"Which component does the actual calculation and instruction execution?","options":["RAM","CPU","SSD","NIC"],"answer":1,"explanation":"The CPU is the processor; RAM is temporary working memory — see ''Hardware''."},{"prompt":"Volatile memory that clears when power is lost is…","options":["the SSD","the BIOS chip","RAM","the hard drive"],"answer":2,"explanation":"RAM is volatile working memory; storage keeps data without power — see ''Hardware''."},{"prompt":"Which of these is an operating system kernel-level open-source OS?","options":["Windows 11","macOS","Linux","Microsoft Office"],"answer":2,"explanation":"Linux is open source; Office is an application, not an OS — see ''Operating systems''."},{"prompt":"The very FIRST step of the standard troubleshooting method is to…","options":["replace the part","identify the problem","document the outcome","reboot everything"],"answer":1,"explanation":"Step 1 is always identify the problem — see ''Troubleshooting''."},{"prompt":"A phone that charges but shows no display most likely has a failed…","options":["SIM card","screen/display assembly","Wi-Fi radio","battery"],"answer":1,"explanation":"Charging proves power; a dead display points to the screen — see ''Mobile devices & printers''."},{"prompt":"Requiring a password plus a code from an app is an example of…","options":["encryption","multi-factor authentication","a firewall","a VPN"],"answer":1,"explanation":"Two different factors = MFA — see ''Security''."},{"prompt":"The best first response to a frustrated user is to…","options":["tell them it''s their fault","listen actively and restate the issue","close the ticket","transfer them immediately"],"answer":1,"explanation":"Active listening builds trust and gathers facts — see the applied project."}]}'::jsonb, null, 10),
  (2, 'Inside the box: hardware components & assembly', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the core PC components and explain what each does during assembly. Warm-up: from the diagnostic, which board does everything else plug into?"},{"heading":"The idea","text":"A computer is a small set of cooperating parts. The *motherboard* is the backbone everything connects to. The *CPU* (processor) executes instructions. *RAM* is fast, volatile working memory — empty it by cutting power. *Storage* (an SSD or hard drive) keeps data permanently. The *power supply (PSU)* converts wall AC into the DC voltages the parts need, and a *GPU* handles graphics. Assembly order matters: seat the CPU and RAM on the board, mount it in the case, connect the PSU, then storage and cards. Before touching components, use an anti-static strap so a static discharge doesn''t kill a chip."},{"heading":"Worked troubleshooting example","text":"A newly built PC powers on — fans spin — but shows nothing on screen and gives no beep. Working the parts: reseat the RAM (a common culprit), confirm the 24-pin and CPU power cables from the PSU are fully clicked in, and check the monitor is plugged into the GPU output, not the motherboard''s. Reseating the RAM restores the display — loose memory was the fault."},{"heading":"Your turn","text":"Which part fits each job? (1) executes program instructions, (2) loses its contents on shutdown, (3) converts AC to DC, (4) stores files permanently, (5) is the board everything else connects to. Answers: 1-CPU, 2-RAM, 3-power supply, 4-storage (SSD/HDD), 5-motherboard."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking more storage speeds up a slow program — that usually needs more RAM or a faster CPU. Mistake: skipping the anti-static strap. Exit: (a) Which memory is volatile? (b) What does the PSU convert? Answers: RAM; wall AC into DC voltages."}]}'::jsonb, 'CPU computes, RAM holds work-in-progress, storage keeps it — three different jobs.', 13),
  (3, 'Operating systems: Windows, macOS, and Linux basics', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what an operating system does and tell the three major desktop families apart. Warm-up: is Microsoft Office an operating system?"},{"heading":"The idea","text":"An *operating system (OS)* sits between hardware and your apps: it manages the CPU and memory, organizes files, controls user accounts and permissions, and provides drivers so devices work. The big desktop families are *Windows* (most common in business; uses drive letters like C: and the Settings/Control Panel), *macOS* (Apple hardware, Unix-based, uses Finder), and *Linux* (open source, many distributions, powerful command line, common on servers). All three share ideas: a file system organized as folders, user accounts with permissions, and a way to install and update software (an app store, package manager, or installer)."},{"heading":"Worked troubleshooting example","text":"A user says ''my Windows PC feels slow.'' Rather than guessing, open Task Manager and read the evidence: one background app is pinned at 100% CPU. End that task and the machine recovers. The lesson: the OS gives you tools (Task Manager on Windows, Activity Monitor on macOS, top on Linux) that turn a vague complaint into a measurable cause."},{"heading":"Your turn","text":"Match the OS to the clue: (1) uses C:\\ drive letters, (2) Finder and comes on Apple hardware, (3) open source with many distributions, (4) the built-in Windows tool to see what''s using the CPU, (5) the app that plays that role on macOS. Answers: 1-Windows, 2-macOS, 3-Linux, 4-Task Manager, 5-Activity Monitor."},{"heading":"Common mistakes & exit ticket","text":"Mistake: calling an application (like a browser or Office) an operating system. Mistake: assuming a fix for one OS works identically on another — paths and tools differ. Exit: (a) Name three things an OS manages. (b) Which OS is open source? Answers: hardware/memory, files, users and permissions; Linux."}]}'::jsonb, 'An OS manages hardware, files, and users; applications run on top of it.', 13),
  (4, 'The troubleshooting method: the six steps', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Apply the six-step troubleshooting method in order to any support problem. Warm-up: what is always step one?"},{"heading":"The idea","text":"Good support is a repeatable process, not luck. The six steps are: (1) *Identify the problem* — gather symptoms, ask the user, note recent changes. (2) *Establish a theory of probable cause* — form a testable guess; question the obvious first. (3) *Test the theory* — confirm or reject it; if it''s wrong, form a new one or escalate. (4) *Establish a plan of action and implement the solution* — fix it with the least disruptive change. (5) *Verify full system functionality* and add preventive measures. (6) *Document findings, actions, and outcomes* so the next person benefits. Backing up data before making changes is a habit that lives across these steps."},{"heading":"Worked troubleshooting example","text":"Ticket: ''I can''t reach the internet.'' (1) Identify: only this PC is affected; it happened after the user moved desks. (2) Theory: the network cable came loose. (3) Test: the link light is off; reseat the cable and it lights. (4) Plan/fix: the cable is fully seated; nothing else changed. (5) Verify: a web page loads and email syncs; suggest a cable clip to prevent a repeat. (6) Document: ''loose Ethernet cable after desk move; reseated; verified connectivity.'' Notice each step earned the next."},{"heading":"Your turn","text":"Put these actions in the right step number (1-6): (a) writing ''reseated cable, verified'' in the ticket, (b) asking what changed recently, (c) guessing the cable is loose, (d) loading a web page to confirm the fix works, (e) reseating the cable, (f) checking the link light. Answers: a-6 (document), b-1 (identify), c-2 (theory), d-5 (verify), e-4 (plan & implement), f-3 (test)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: jumping straight to a fix (step 4) before identifying or testing — you treat symptoms, not causes. Mistake: skipping step 6, leaving no record. Exit: (a) What is step 1? (b) What is step 6? Answers: identify the problem; document findings, actions, and outcomes."}]}'::jsonb, 'Identify → theorize → test → plan & fix → verify → document. Never skip steps.', 14),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"RAM is best described as…","options":["permanent storage","fast volatile working memory","the processor","a graphics card"],"answer":1,"explanation":"RAM holds work in progress and clears on power loss."},{"prompt":"Before handling internal components you should…","options":["remove the CPU first","wear an anti-static strap","unplug the monitor only","update the BIOS"],"answer":1,"explanation":"Static discharge can destroy chips."},{"prompt":"Which is an operating system, not an application?","options":["Chrome","Linux","Photoshop","Excel"],"answer":1,"explanation":"Linux is an OS; the others run on top of one."},{"prompt":"Step 2 of the troubleshooting method is to…","options":["document the outcome","establish a theory of probable cause","verify functionality","identify the problem"],"answer":1,"explanation":"After identifying, you form a testable theory."},{"prompt":"The Windows tool to see what is using the CPU is…","options":["Finder","Task Manager","Control Panel","Disk Cleanup"],"answer":1,"explanation":"Task Manager shows per-process CPU and memory use."},{"prompt":"The final troubleshooting step is to…","options":["reboot","escalate","document findings and outcomes","replace the motherboard"],"answer":2,"explanation":"Step 6 records what happened for the next tech."}]}'::jsonb, null, 8),
  (6, 'Mobile devices & printers', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Support common phone, tablet, and printer problems without swapping parts blindly. Warm-up: if a phone charges but the screen stays black, which part is suspect?"},{"heading":"The idea","text":"*Mobile devices* are computers with tight integration: battery, display, radios (cellular, Wi-Fi, Bluetooth), and a SIM or eSIM for cellular service. Many issues are software — a stuck app, a full storage volume, or an update — so a restart and a storage check come before any hardware theory. *Printers* fail in predictable places: the *queue* (stuck jobs), *connectivity* (USB, Wi-Fi, or network address), *drivers* (the software that translates a document into printer instructions), and *consumables/hardware* (toner, ink, or a paper jam). Match the symptom to the layer instead of guessing."},{"heading":"Worked troubleshooting example","text":"Ticket: ''nothing prints and jobs pile up.'' Identify: other users can print to the same printer, so the printer and network are fine. Theory: this PC''s print queue is stuck. Test: open the queue and see three jammed jobs. Plan/fix: cancel the stuck jobs and restart the print spooler service. Verify: a test page prints. Document: ''stuck local queue; cleared jobs, restarted spooler; test page OK.'' The ''others can print'' clue saved a needless toner swap."},{"heading":"Your turn","text":"Pick the most likely layer for each: (1) phone screen black but it vibrates and charges, (2) faint, streaky printout, (3) a single app crashes on launch, (4) printer offline only after an IP change, (5) phone can''t join Wi-Fi but cellular works. Answers: 1-display/hardware, 2-consumable (low toner/ink), 3-software/app, 4-connectivity/network, 5-Wi-Fi radio or settings."},{"heading":"Common mistakes & exit ticket","text":"Mistake: replacing toner for every faint page when the real fix may be a cleaning cycle or wrong driver. Mistake: assuming any phone problem is hardware before trying a restart and storage check. Exit: (a) Name two printer failure layers. (b) First cheap step for a misbehaving app? Answers: queue, connectivity, drivers, or consumables (any two); restart the device/app."}]}'::jsonb, 'Isolate the layer: is it power, the OS/app, the network, or the physical device?', 12),
  (7, 'Security & safe practices', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Apply everyday security and safety habits that protect users, data, and yourself. Warm-up: a password plus a code from an app is an example of what?"},{"heading":"The idea","text":"Security rests on a few durable ideas. *Authentication* proves identity; *multi-factor authentication (MFA)* combines two different factors (something you know, have, or are) so a stolen password isn''t enough. *Authorization* grants the least privilege needed — no more. *Encryption* scrambles data so only holders of a key can read it, protecting laptops and drives if lost. *Malware* (viruses, ransomware, spyware) often arrives through *phishing* — deceptive messages that trick users into clicking or sharing credentials. Physical safety matters too: an anti-static strap protects hardware, and proper handling of power and batteries protects you. The strongest control is a trained, skeptical user."},{"heading":"Worked troubleshooting example","text":"Ticket: ''I got an email saying my account is locked — click here to fix it.'' Identify: the sender domain is misspelled and the link points to an unrelated address. Theory: this is phishing. Test: hover the link (don''t click) and confirm the mismatch; check with the real service directly. Plan/fix: do not click; report the message, and if a credential was entered, reset the password and enable MFA. Verify: the account is secured and monitored. Document: ''phishing attempt reported; credentials reset; MFA enabled.''"},{"heading":"Your turn","text":"Label each: (1) password + phone code, (2) giving a user only the folders their job needs, (3) scrambling a laptop''s drive, (4) a fake ''reset your password'' email, (5) software that encrypts your files for ransom. Answers: 1-multi-factor authentication, 2-least privilege / authorization, 3-encryption, 4-phishing, 5-ransomware (malware)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating MFA as optional ''because I have a strong password'' — passwords leak. Mistake: giving admin rights when a standard account would do. Exit: (a) What does encryption protect? (b) What does ''least privilege'' mean? Answers: data confidentiality if a device or drive is lost/stolen; grant only the access a role actually needs."}]}'::jsonb, 'Authentication proves who you are; authorization decides what you may do.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"motherboard","translation":"the main circuit board that connects the CPU, RAM, storage, and other components","example":"The technician seated the CPU and RAM on the motherboard before mounting it in the case."},{"term":"RAM","translation":"fast, volatile working memory that holds active data and clears when power is lost","example":"Adding RAM let the slow PC run more apps at once."},{"term":"operating system","translation":"the software that manages hardware, files, and users so applications can run","example":"Windows, macOS, and Linux are the three major desktop operating systems."},{"term":"troubleshooting method","translation":"the six-step process: identify, theorize, test, plan and fix, verify, document","example":"She followed the troubleshooting method instead of guessing at the fix."},{"term":"multi-factor authentication","translation":"logging in with two different factors, such as a password plus a phone code","example":"Multi-factor authentication stopped the attacker even though the password had leaked."},{"term":"phishing","translation":"a deceptive message that tricks a user into clicking a link or revealing credentials","example":"The misspelled sender address gave the phishing email away."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"A phone that charges but shows a black, vibrating screen most likely has a bad…","options":["battery","SIM card","display assembly","Wi-Fi radio"],"answer":2,"explanation":"Charging and vibration prove power; a dead screen points to the display."},{"prompt":"When jobs pile up on one PC but others can print, the fix is usually to…","options":["replace the toner","clear the stuck queue and restart the spooler","buy a new printer","reinstall the OS"],"answer":1,"explanation":"The problem is local; others printing rules out the printer itself."},{"prompt":"Multi-factor authentication requires…","options":["two passwords","two different factors","a longer password","a firewall"],"answer":1,"explanation":"Different factors (know/have/are), not two of the same."},{"prompt":"Granting a user only the access their job needs is called…","options":["encryption","least privilege","phishing","authentication"],"answer":1,"explanation":"Least privilege limits authorization to what''s necessary."},{"prompt":"Encryption primarily protects…","options":["against paper jams","data confidentiality if a device is lost","the power supply","printer drivers"],"answer":1,"explanation":"Scrambled data is unreadable without the key."},{"prompt":"A misspelled sender and a mismatched link are signs of…","options":["a driver error","phishing","low RAM","a stuck queue"],"answer":1,"explanation":"These are classic phishing indicators."}]}'::jsonb, null, 8),
  (10, 'Applied project: resolve a support ticket end to end', 'writing', '{"sections":[{"heading":"The task","text":"Take one realistic ticket and work it fully, in writing, as if you were on the help desk. Ticket: ''My laptop was fine yesterday. Today it''s very slow, and a printer I use won''t print my report. I have a deadline in an hour and I''m stressed.'' Write your handling of the whole interaction — you''re being judged on process and communication, not on inventing a lucky fix."},{"heading":"Milestones","text":"1) Open with active listening: restate the issue and acknowledge the deadline pressure in one professional sentence. 2) Apply the six steps to the SLOW laptop: identify (what changed? questions to ask), a theory, how you''d test it, the least-disruptive fix, and how you''d verify. 3) Apply the six steps to the PRINTER separately: note the clue that isolates whether it''s the queue, connectivity, drivers, or a consumable. 4) State one security or safety habit you''d respect while working (for example, backing up data before changes, or not clicking an unknown link the user mentions). 5) Close the ticket: write the one- or two-line documentation entry (findings, actions, outcome) and a courteous closing line to the user."},{"heading":"Self-check rubric","text":"✔ You opened by listening and restating, not by guessing a fix. ✔ Each problem is worked through all six steps in order, with a testable theory before any change. ✔ You isolated the printer fault by layer using an observable clue. ✔ You named a real security or safety habit. ✔ Your documentation states findings, actions, and outcome in plain language, and your closing line is courteous. If all five are true, you handled the ticket like a professional."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0002-0000-4000-8000-00000000000c' and l.position = v.pos
);
